const result = $input.first().json;
const text = [result.message, result.error].filter(Boolean).join(' ').toLowerCase();
const needsInput = [
  'captcha',
  'human verification',
  'verify you are human',
  'otp',
  'one-time',
  '2fa',
  'two-factor',
  'login',
  'sign in',
  'missing',
  'required',
  'authorization',
  'work authorization'
].some((needle) => text.includes(needle));
const success = Boolean(result.success && result.completed);
return [{
  json: {
    status: success ? 'success' : needsInput ? 'needs_input' : 'failed',
    currentStep: success ? 'Application submitted' : needsInput ? 'Manual attention needed' : 'Browser automation stopped',
    message: result.message || (success ? 'Application submitted successfully.' : needsInput ? 'The site needs manual attention before automation can continue.' : 'Browserbase could not complete the application.'),
    blockingQuestion: needsInput ? (result.message || 'Please handle the site blocker and try again.') : undefined,
    inputField: needsInput ? 'manual_review' : undefined,
    sessionId: result.sessionId || null,
    actions: Array.isArray(result.actions) ? result.actions : [],
    usage: result.usage || {},
    raw: result
  }
}];
